// ============================================================
// PARSE AI AGENT RESPONSE — robust extraction + normalisation
// ============================================================

const items = $input.all();
const item = items[0];
const content = item.json;

// Pull raw text from wherever n8n puts it
let rawText = '';
try {
  rawText = content?.output
    ?? content?.message?.content
    ?? content?.choices?.[0]?.message?.content
    ?? content?.text
    ?? JSON.stringify(content);
} catch(e) {
  rawText = JSON.stringify(content);
}

// Strip markdown code fences if model wraps in them
const clean = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    intent: 'unknown',
    needs_db: false,
    email_in_history: false,
    extracted_email: null,
    confidence: 0,
    response: 'I had trouble understanding that. Please contact our support team at https://bookleafpublishing.freshdesk.com/support/tickets/new'
  };
}

// Normalise all fields with safe defaults
const intent = String(parsed.intent ?? 'unknown').trim();
let needs_db = parsed.needs_db === true || parsed.needs_db === 'true';
const email_in_history = parsed.email_in_history === true || parsed.email_in_history === 'true';
const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : parseFloat(parsed.confidence ?? '0');
const response = String(parsed.response ?? '').trim();

// Email: normalise to clean string or empty string
let extracted_email = '';
if (parsed.extracted_email && parsed.extracted_email !== 'null' && String(parsed.extracted_email).includes('@')) {
  extracted_email = String(parsed.extracted_email).trim().toLowerCase();
}

// ENFORCE DB ROUTE IF EMAIL IS PRESENT
if (extracted_email && !['greeting', 'general_faq'].includes(intent)) {
  needs_db = true;
}

return [{
  json: {
    intent,
    needs_db,
    email_in_history,
    extracted_email,
    confidence,
    gpt_response: response,
    original_query: $('Chat Trigger').first().json.chatInput ?? ''
  }
}];

// AI ERROR HANDLER — fires if AI Agent itself errored
return [{
  json: {
    intent: 'unknown',
    needs_db: false,
    email_in_history: false,
    extracted_email: '',
    confidence: 0,
    gpt_response: 'Our AI assistant is temporarily unavailable. Please try again in a moment or raise a support ticket at https://bookleafpublishing.freshdesk.com/support/tickets/new',
    original_query: $('Chat Trigger').first().json.chatInput ?? '',
    route: 'ai_error'
  }
}];

// ============================================================
// DB RESULT PROCESSOR
// ============================================================

const items = $input.all();
const item = items[0];
const data = item.json;

const intent = $('Parse GPT JSON').first().json.intent ?? 'unknown';
const extracted_email = $('Parse GPT JSON').first().json.extracted_email ?? '';
const original_query = $('Parse GPT JSON').first().json.original_query ?? '';
const confidence = $('Parse GPT JSON').first().json.confidence ?? 0.9;

let final_response = '';
let route = 'db_success';

// ------------------------------------------------------------
// ERROR CHECK
// ------------------------------------------------------------

if (!data || data.error) {
  final_response =
    'We are having trouble reaching our systems right now. Please raise a support ticket and our team will respond within 24 hours:\n\nhttps://bookleafpublishing.freshdesk.com/support/tickets/new';

  route = 'db_down';

  return [
    {
      json: {
        final_response,
        route,
        intent,
        extracted_email,
        confidence,
        original_query,
      },
    },
  ];
}

// ------------------------------------------------------------
// AUTHOR DATA
// ------------------------------------------------------------

const author = data;

const bookTitle = author.book_title ?? 'your book';
const bookLiveDate = author.book_live_date ?? null;
const royaltyStatus = author.royalty_status ?? 'Pending';
const submissionDate = author.final_submission_date ?? null;
const isbn = author.isbn ?? null;
const addOns = Array.isArray(author.add_on_services)
  ? author.add_on_services.join(', ')
  : 'None';

const name = author.name
  ? `Hi ${author.name.split(' ')[0]}, `
  : '';

// ------------------------------------------------------------
// INTENT HANDLING
// ------------------------------------------------------------

if (intent === 'book_live_status') {

  if (bookLiveDate) {

    final_response =
      `${name}Your book **"${bookTitle}"** went live on **${bookLiveDate}**.` +
      `${isbn ? ` Your ISBN is \`${isbn}\`.` : ''} ` +
      `You can find it on the BookLeaf bookstore right now.`;

  } else {

    final_response =
      `${name}Your book **"${bookTitle}"** is currently being processed and is not live yet.` +
      `${submissionDate ? ` We received your submission on ${submissionDate}.` : ''} ` +
      `Publishing typically takes 30 to 45 business days. We will email you as soon as it goes live.`;
  }

} else if (intent === 'royalty_status') {

  const royaltyMap = {
    Pending:
      'not yet generated. It will be available once your book has active sales.',

    Processing:
      'currently being processed by our finance team.',

    Paid:
      'already paid out. Check your registered bank details or email for the transfer.',
  };

  const royaltyNote =
    royaltyMap[royaltyStatus] ?? royaltyStatus;

  final_response =
    `${name}Your royalty status for **"${bookTitle}"** is: **${royaltyStatus}**. ` +
    `This means it is ${royaltyNote}\n\n` +
    `Reminder: BookLeaf pays 80% royalty on profits. ` +
    `For a detailed breakdown, raise a ticket:\n` +
    `https://bookleafpublishing.freshdesk.com/support/tickets/new`;

} else if (intent === 'author_copy') {

  if (bookLiveDate) {

    final_response =
      `${name}Your free author copy coupon for **"${bookTitle}"** should have been sent ` +
      `to your registered email after publication on **${bookLiveDate}**. ` +
      `Please check your inbox and spam folder.\n\n` +
      `If you still cannot find it, raise a ticket:\n` +
      `https://bookleafpublishing.freshdesk.com/support/tickets/new`;

  } else {

    final_response =
      `${name}Your author copy coupon will be sent once **"${bookTitle}"** is published. ` +
      `The book is still being processed. We will notify you by email once it is ready.`;
  }

} else if (intent === 'add_on_status') {

  final_response =
    `${name}Here are the add-on services on your account for **"${bookTitle}"**:\n\n` +
    `${addOns}\n\n` +
    `If anything looks incorrect or you would like to add a service, raise a ticket:\n` +
    `https://bookleafpublishing.freshdesk.com/support/tickets/new`;

} else {

  final_response =
    `${name}Here is a summary of your account:\n\n` +
    `Book: **"${bookTitle}"**\n` +
    `Submitted: ${submissionDate ?? 'N/A'}\n` +
    `Live date: ${bookLiveDate ?? 'Pending'}\n` +
    `Royalty status: ${royaltyStatus}\n` +
    `Add-ons: ${addOns}\n\n` +
    `Please let me know if you need anything else.`;
}

// ------------------------------------------------------------
// SUCCESS
// ------------------------------------------------------------

route = 'db_success';

return [
  {
    json: {
      final_response,
      route,
      intent,
      extracted_email,
      confidence,
      original_query,
    },
  },
];
